function modal() {
  const copy = {
    profile: ["Profiel","Hier zou de gebruiker zijn profiel, taalvoorkeur en uitlogactie beheren."],
    trainer: ["Trainer gestart","In het echte product opent hier de getimede vragenflow met voortgang, timer en directe feedback."],
    invite: ["Nieuwe uitnodiging","Dit prototype simuleert het uitnodigingsformulier zonder gegevens te versturen."],
  }[state.modal] || ["Factcard","Hier opent een verdiepende naslagkaart met gerelateerde lessen en aanvullende uitleg."];
  return `<div class="modal-backdrop" data-close-modal><div class="modal-card" role="dialog" aria-modal="true" aria-labelledby="modal-title" aria-describedby="modal-desc"><h2 id="modal-title">${copy[0]}</h2><p id="modal-desc">${copy[1]}</p><button class="btn" id="modal-close" data-close-modal>Sluiten</button></div></div>`;
}

function profielView() {
  const u = currentUser;
  const editing = state.profileEdit;
  const msg = state.profileMsg;
  const pwMsg = state.pwMsg;
  return shell(`
    <main class="main profile-main">
      <button class="breadcrumb" data-route="dashboard">← Terug naar dashboard</button>
      <div class="page-head"><div><h1>Mijn profiel</h1><p>Bekijk en wijzig je accountgegevens.</p></div></div>

      <div class="profile-grid">
        <div class="card profile-identity">
          <div class="profile-avatar-lg">${initials(u.name)}</div>
          <h2 class="profile-name">${escapeAttr(u.name)}</h2>
          <span class="profile-email">${escapeAttr(u.email)}</span>
          <span class="profile-role-badge">${icon("shield")} ${u.role}</span>
        </div>

        <div class="card profile-details">
          <div class="profile-card-head">
            <h3>Accountgegevens</h3>
            ${editing ? "" : `<button class="btn secondary" data-profile-edit>Bewerken</button>`}
          </div>

          ${msg ? `<div class="profile-flash ${msg.type}">${msg.type === "success" ? icon("check") : "<span class='flash-ico'>!</span>"}<span>${msg.text}</span></div>` : ""}

          ${editing ? `
          <form id="profile-form" class="profile-form" novalidate>
            <label class="field">
              <span>Naam</span>
              <div class="input-wrap">${icon("user")}<input id="pf-name" type="text" value="${escapeAttr(u.name)}" autocomplete="name" /></div>
            </label>
            <label class="field">
              <span>E-mailadres</span>
              <div class="input-wrap">${icon("mail")}<input id="pf-email" type="email" value="${escapeAttr(u.email)}" autocomplete="email" /></div>
            </label>
            <div class="profile-actions">
              <button type="submit" class="btn-course-action profile-save-btn">Opslaan</button>
              <button type="button" class="btn ghost" data-profile-cancel>Annuleren</button>
            </div>
          </form>
          ` : `
          <dl class="profile-readonly">
            <div><dt>Naam</dt><dd>${escapeAttr(u.name)}</dd></div>
            <div><dt>E-mailadres</dt><dd>${escapeAttr(u.email)}</dd></div>
            <div><dt>Rol</dt><dd>${escapeAttr(u.role)}</dd></div>
          </dl>
          `}
        </div>
      </div>

      <div class="card profile-meta">
        <h3>Accountinformatie</h3>
        <dl class="profile-readonly two-col">
          <div><dt>Accountstatus</dt><dd><span class="status-pill">${u.status}</span></dd></div>
          <div><dt>Aangemeld sinds</dt><dd>${u.joined}</dd></div>
        </dl>
      </div>

      <div class="card profile-password">
        <h3>Wachtwoord wijzigen</h3>
        ${pwMsg ? `<div class="profile-flash ${pwMsg.type}">${pwMsg.type === "success" ? icon("check") : "<span class='flash-ico'>!</span>"}<span>${pwMsg.text}</span></div>` : ""}
        <form id="password-form" class="profile-form" novalidate>
          <label class="field"><span>Huidig wachtwoord</span><div class="input-wrap"><input id="pw-current" type="password" autocomplete="current-password" /></div></label>
          <label class="field"><span>Nieuw wachtwoord</span><div class="input-wrap"><input id="pw-new" type="password" autocomplete="new-password" /></div></label>
          <label class="field"><span>Bevestig nieuw wachtwoord</span><div class="input-wrap"><input id="pw-confirm" type="password" autocomplete="new-password" /></div></label>
          <div class="profile-actions">
            <button type="submit" class="btn-course-action pw-save-btn">Wachtwoord bijwerken</button>
          </div>
        </form>
      </div>
    </main>
  `, "");
}

function render() {
  const views = { login:loginView, dashboard:dashboardView, course:courseView, lesson:lessonView, trainer:trainerView, factcards:()=>factcardsView(state.factFilter), factcard:()=>factcardDetailView(state.activeFact), progress:progressView, admin:adminView, profiel:profielView };
  app.innerHTML = (views[state.route]||dashboardView)();
  const eqiFrame = document.getElementById("eqi-frame");
  if (eqiFrame) {
    const les = lessonById();
    const s = String(Math.min(Math.max(state.step, 1), (les && les.steps) || 6));
    if (eqiFrame.dataset.eqiStep !== s) {
      eqiFrame.dataset.eqiStep = s;
      const doc = (les && les.embed === "interesses") ? interessesModelHtml : (les && les.embed === "waarden") ? waardenModelHtml : ((s === "1" || s === "2" || s === "3") ? eqiSegWheelHtml : eqiWheelHtml);
      eqiFrame.srcdoc = doc.replace("__EQI_STEP__", s);
    }
    sizeEqiFrame();
  }
  document.querySelectorAll(".ls-discgrid-frame").forEach((f) => {
    if (!f.srcdoc) {
      f.srcdoc = discGridHtml;
      f.addEventListener("load", () => sizeDiscFrame(f), { once: true });
    }
  });
}

function sizeDiscFrame(f) {
  try {
    const body = f.contentDocument && f.contentDocument.body;
    if (!body) return;
    const apply = () => { f.style.height = Math.max(420, body.scrollHeight) + "px"; };
    apply();
    if ("ResizeObserver" in window) new ResizeObserver(apply).observe(body);
  } catch (err) { /* cross-origin fallback: keep default CSS height */ }
}


function sizeEqiFrame() {
  const f = document.getElementById("eqi-frame");
  if (!f) return;
  const top = f.getBoundingClientRect().top;
  const footer = document.querySelector(".eqi-bottombar");
  const fh = footer ? footer.getBoundingClientRect().height + 18 : 96;
  f.style.height = Math.max(380, window.innerHeight - top - fh) + "px";
}
window.addEventListener("resize", sizeEqiFrame);
window.addEventListener("message", (e) => {
  if (e && e.data && typeof e.data.eqiHeight === "number") sizeEqiFrame();
});

document.addEventListener("click", (e) => {
  const t = e.target.closest("button,a");
  if (state.menuOpen && !e.target.closest(".account")) {
    state.menuOpen = false;
    if (!t) { render(); return; }
  }
  if (!t) return;
  if (t.hasAttribute("data-account-toggle")) { navigate(state.route, { menuOpen: !state.menuOpen }); return; }
  if (t.hasAttribute("data-goto-profile")) { navigate("profiel", { menuOpen: false, profileEdit: false, profileMsg: null, pwMsg: null }); return; }
  if (t.hasAttribute("data-logout")) { navigate("login", { menuOpen: false }); return; }
  if (t.hasAttribute("data-profile-edit")) { navigate("profiel", { profileEdit: true, profileMsg: null }); return; }
  if (t.hasAttribute("data-profile-cancel")) { navigate("profiel", { profileEdit: false, profileMsg: null }); return; }
  if (t.hasAttribute("data-back")) { navigate(state.prevRoute || "dashboard", { menuOpen: false }); return; }
  if (t.dataset.route) navigate(t.dataset.route, { menuOpen: false });
  if (t.dataset.course) navigate("course", { activeCourse:Number(t.dataset.course), factFilter:null });
  if (t.dataset.lesson) navigate("lesson", { activeLesson:t.dataset.lesson, activeCourse:Number(t.dataset.courseId), step:1, selectedAnswer:"", gb:null, ls:null });
  if (t.dataset.trainer) navigate("trainer", { activeCourse:Number(t.dataset.trainer) });
  if (t.dataset.factFilter) navigate("factcards", { factFilter:Number(t.dataset.factFilter) });
  if (t.dataset.factDetail) navigate("factcard", { activeFact:Number(t.dataset.factDetail) });
  if (t.dataset.step) navigate("lesson", { step:Number(t.dataset.step), selectedAnswer:"", gb:null, ls:null });
  if (t.hasAttribute("data-prev-step")) navigate("lesson", { step:Math.max(1,state.step-1), selectedAnswer:"", gb:null, ls:null });
  if (t.hasAttribute("data-next-step")) {
    const l = lessonById();
    if (state.step >= l.steps) {
      const c = courses.find(c => c.id === state.activeCourse);
      if (c) {
        const les = c.lessons.find(x => x.id === state.activeLesson);
        if (les) les.done = true;
        const totaal = c.lessons.length;
        const klaar = c.lessons.filter(x => x.done !== false).length;
        c.progress = totaal ? Math.round(klaar / totaal * 100) : 0;
      }
      navigate("course", { activeCourse:l.courseId });
    }
    else navigate("lesson", { step:state.step+1, selectedAnswer:"", gb:null, ls:null });
  }
  if (t.dataset.answer) navigate("lesson", { selectedAnswer:t.dataset.answer });
  if (t.dataset.adminTab) navigate("admin", { adminTab:t.dataset.adminTab });
  if (t.dataset.modal) navigate(state.route, { modal:t.dataset.modal });
  if (t.hasAttribute("data-close-modal")) navigate(state.route, { modal:null });
});


document.addEventListener("keydown", (e) => {
  if (e.key === "Escape" && state.modal) navigate(state.route, { modal: null });
  else if (e.key === "Escape" && state.menuOpen) navigate(state.route, { menuOpen: false });
});

document.addEventListener("submit", (e) => {
  if (e.target.matches("[data-login]")) { e.preventDefault(); navigate("dashboard"); return; }
  if (e.target.id === "profile-form") {
    e.preventDefault();
    const name = (document.getElementById("pf-name").value || "").trim();
    const email = (document.getElementById("pf-email").value || "").trim();
    if (!name) return navigate("profiel", { profileEdit: true, profileMsg: { type: "error", text: "Naam mag niet leeg zijn." } });
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return navigate("profiel", { profileEdit: true, profileMsg: { type: "error", text: "Voer een geldig e-mailadres in." } });
    currentUser.name = name;
    currentUser.email = email;
    return navigate("profiel", { profileEdit: false, profileMsg: { type: "success", text: "Gegevens opgeslagen." } });
  }
  if (e.target.id === "password-form") {
    e.preventDefault();
    const cur = document.getElementById("pw-current").value;
    const nw = document.getElementById("pw-new").value;
    const cf = document.getElementById("pw-confirm").value;
    if (!cur || !nw || !cf) return navigate("profiel", { pwMsg: { type: "error", text: "Vul alle wachtwoordvelden in." } });
    if (nw.length < 8) return navigate("profiel", { pwMsg: { type: "error", text: "Nieuw wachtwoord moet minimaal 8 tekens bevatten." } });
    if (nw !== cf) return navigate("profiel", { pwMsg: { type: "error", text: "De nieuwe wachtwoorden komen niet overeen." } });
    return navigate("profiel", { pwMsg: { type: "success", text: "Wachtwoord bijgewerkt." } });
  }
});

render();


document.addEventListener("click", (e) => {
  const t = e.target.closest("[data-gb-check],[data-gb-verify],[data-gb-tf],[data-gb-verify-tf],[data-gb-mc],[data-gb-verify-mc],[data-gb-brain],[data-gb-openall],[data-gb-move],[data-gb-verify-match],[data-gb-tip]");
  if (!t) return;
  const gb = gbState();
  if (t.hasAttribute("data-gb-tip")) { gb.tipOpen = true; render(); return; }
  if (t.hasAttribute("data-gb-check")) { const i = t.getAttribute("data-gb-check"); gb.checks[i] = !gb.checks[i]; render(); return; }
  if (t.hasAttribute("data-gb-verify")) {
    gb.result = gbQuiz13.opties.every((o, i) => !!gb.checks[i] === o.juist);
    render(); return;
  }
  if (t.hasAttribute("data-gb-tf")) { gb.tf = t.getAttribute("data-gb-tf"); render(); return; }
  if (t.hasAttribute("data-gb-verify-tf")) { gb.tfResult = gb.tf === "Juist"; render(); return; }
  if (t.hasAttribute("data-gb-mc")) { gb.mc = t.getAttribute("data-gb-mc"); render(); return; }
  if (t.hasAttribute("data-gb-verify-mc")) { gb.mcResult = gb.mc === "De rangorde van behoeften"; render(); return; }
  if (t.hasAttribute("data-gb-brain")) { const id = t.getAttribute("data-gb-brain"); gb.brain[id] = !gb.brain[id]; render(); return; }
  if (t.hasAttribute("data-gb-openall")) {
    const allOpen = gbBrein.every(b => gb.brain[b.id]);
    gbBrein.forEach(b => { gb.brain[b.id] = !allOpen; });
    render(); return;
  }
  if (t.hasAttribute("data-gb-move")) {
    const [row, dir] = t.getAttribute("data-gb-move").split(":").map(Number);
    const other = row + dir;
    if (other >= 0 && other < gb.order.length) {
      [gb.order[row], gb.order[other]] = [gb.order[other], gb.order[row]];
    }
    render(); return;
  }
  if (t.hasAttribute("data-gb-verify-match")) {
    gb.matchResult = gb.order.every((v, i) => v === i);
    render(); return;
  }
});

document.addEventListener("click", (e) => {
  const t = e.target.closest("[data-ls-mc],[data-ls-verify-mc],[data-ls-tf],[data-ls-verify-tf],[data-ls-check],[data-ls-verify-check],[data-ls-cat],[data-ls-verify-cat],[data-ls-scale],[data-ls-quad],[data-ls-quadall]");
  if (!t) return;
  const ls = lsState();
  if (t.hasAttribute("data-ls-check")) { const i = t.getAttribute("data-ls-check"); ls.checks[i] = !ls.checks[i]; render(); return; }
  if (t.hasAttribute("data-ls-verify-check")) {
    const correct = t.getAttribute("data-ls-verify-check").split(",").map(Number);
    const total = Number(t.getAttribute("data-ls-total"));
    ls.checkResult = Array.from({ length: total }, (_, i) => !!ls.checks[i] === correct.includes(i)).every(Boolean);
    render(); return;
  }
  if (t.hasAttribute("data-ls-mc")) { ls.mc = t.getAttribute("data-ls-mc"); render(); return; }
  if (t.hasAttribute("data-ls-verify-mc")) { ls.mcResult = ls.mc === t.getAttribute("data-ls-verify-mc"); render(); return; }
  if (t.hasAttribute("data-ls-tf")) { ls.tf = t.getAttribute("data-ls-tf"); render(); return; }
  if (t.hasAttribute("data-ls-verify-tf")) { ls.tfResult = ls.tf === t.getAttribute("data-ls-verify-tf"); render(); return; }
  if (t.hasAttribute("data-ls-cat")) {
    const [idx, cat] = t.getAttribute("data-ls-cat").split(":");
    ls.cats[idx] = cat;
    render(); return;
  }
  if (t.hasAttribute("data-ls-verify-cat")) {
    const pairs = t.getAttribute("data-ls-verify-cat").split("|").map(s => s.split(":"));
    ls.catResult = pairs.every(([idx, cat]) => ls.cats[idx] === cat);
    render(); return;
  }
  if (t.hasAttribute("data-ls-scale")) {
    const [axis, val] = t.getAttribute("data-ls-scale").split(":");
    ls[axis] = Number(val);
    render(); return;
  }
  if (t.hasAttribute("data-ls-quad")) { const id = t.getAttribute("data-ls-quad"); ls.quad[id] = !ls.quad[id]; render(); return; }
  if (t.hasAttribute("data-ls-quadall")) {
    const ids = t.getAttribute("data-ls-quadall").split(",");
    const allOpen = ids.every(id => ls.quad[id]);
    ids.forEach(id => { ls.quad[id] = !allOpen; });
    render(); return;
  }
});
